import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const categories = ['Books', 'Gadgets', 'Notes', 'Accessories'];

const ProductForm = () => {
  const navigate = useNavigate();
  const [values, setValues] = useState({
    title: '',
    price: '',
    category: 'Books',
    description: '',
    image: null
  });
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  const handleChange = (field) => (event) => {
    const value = field === 'image' ? event.target.files?.[0] || null : event.target.value;
    setValues((prev) => ({ ...prev, [field]: value }));
    setError('');
    setMessage('');
  };

  const handleDrop = (event) => {
    event.preventDefault();
    const file = event.dataTransfer.files?.[0];
    if (file) {
      setValues((prev) => ({ ...prev, image: file }));
      setError('');
      setMessage('Image ready to upload');
    }
  };

  const handleSubmit = (event) => {
    event.preventDefault();

    if (!values.title || !values.price || !values.description) {
      setError('Please complete all required fields before posting.');
      return;
    }

    setMessage('Your item is ready! Redirecting to dashboardâ€¦');
    setTimeout(() => navigate('/dashboard'), 1200);
  };

  return (
    <main className="page-shell form-page">
      <section className="form-panel">
        <div className="form-intro">
          <p className="eyebrow">Post Item</p>
          <h1>List your item in a premium form</h1>
          <p className="section-copy">
            Upload details, choose a category, and share your listing with the campus community instantly.
          </p>
        </div>

        <div className="form-card">
          <div
            className="upload-dropzone"
            onDragOver={(e) => e.preventDefault()}
            onDrop={handleDrop}
          >
            <div>
              <p className="drop-title">Drag & drop an image</p>
              <p className="drop-copy">or click to browse your files</p>
              <input type="file" accept="image/*" onChange={handleChange('image')} className="file-input" />
            </div>
            {values.image && <p className="drop-note">Selected: {values.image.name}</p>}
          </div>

          <form onSubmit={handleSubmit} className="listing-form">
            <div className="input-grid">
              <label className="input-group">
                <span>Title</span>
                <input
                  type="text"
                  value={values.title}
                  onChange={handleChange('title')}
                  placeholder="Compact DSLR lens"
                />
              </label>

              <label className="input-group">
                <span>Price</span>
                <input
                  type="number"
                  value={values.price}
                  onChange={handleChange('price')}
                  placeholder="29"
                />
              </label>

              <label className="input-group">
                <span>Category</span>
                <select value={values.category} onChange={handleChange('category')}>
                  {categories.map((category) => (
                    <option key={category} value={category}>
                      {category}
                    </option>
                  ))}
                </select>
              </label>
            </div>

            <label className="input-group input-full">
              <span>Description</span>
              <textarea
                value={values.description}
                onChange={handleChange('description')}
                rows="5"
                placeholder="Add a short description for students"
              />
            </label>

            {error && <div className="form-alert error-alert">{error}</div>}
            {message && <div className="form-alert success-alert">{message}</div>}

            <div className="form-actions">
              <button type="submit" className="gradient-btn">
                Publish Listing
              </button>
              <button type="button" className="subtle-btn" onClick={() => navigate('/')}>Cancel</button>
            </div>
          </form>
        </div>
      </section>
    </main>
  );
};

export default ProductForm;
